","import React from "react";
import { Select } from "@servicenow/react-components/Select";
import { Input } from "@servicenow/react-components/Input";

const MONTHS = [
 { id: "01", label: "January" }, { id: "02", label: "February" },
 { id: "03", label: "March" }, { id: "04", label: "April" },
 { id: "05", label: "May" }, { id: "06", label: "June" },
 { id: "07", label: "July" }, { id: "08", label: "August" },
 { id: "09", label: "September" }, { id: "10", label: "October" },
 { id: "11", label: "November" }, { id: "12", label: "December" },
];

const YEARS = Array.from({ length: 11 }, (_, i) => {
 const y = String(2020 + i);
 return { id: y, label: y };
});

interface FilterProps {
 fromMonth: string;
 fromYear: string;
 toMonth: string;
 toYear: string;
 searchText: string;
 onFromMonthChange: (v: string) => void;
 onFromYearChange: (v: string) => void;
 onToMonthChange: (v: string) => void;
 onToYearChange: (v: string) => void;
 onSearchChange: (v: string) => void;
}

export default function TransactionFilters(props: FilterProps) {
 const sel = (handler: (v: string) => void) => (e: any) =>
 handler(e.detail.item.id);

 return (
 <div className="txn-filters">
 <div className="txn-filters__row">
 <div className="txn-filters__group">
 <span className="txn-filters__label">From</span>
 <Select label="From Month" items={MONTHS}
 selectedItem={props.fromMonth}
 onSelectedItemSet={sel(props.onFromMonthChange)} />
 <Select label="From Year" items={YEARS}
 selectedItem={props.fromYear}
 onSelectedItemSet={sel(props.onFromYearChange)} />
 </div>
 <div className="txn-filters__group">
 <span className="txn-filters__label">To</span>
 <Select label="To Month" items={MONTHS}
 selectedItem={props.toMonth}
 onSelectedItemSet={sel(props.onToMonthChange)} />
 <Select label="To Year" items={YEARS}
 selectedItem={props.toYear}
 onSelectedItemSet={sel(props.onToYearChange)} />
 </div>
 </div>
 <div className="txn-filters__search">
 <Input label="Search Transactions" value={props.searchText}
 placeholder="Search by description..."
 onInput={(e: any) => props.onSearchChange(e.target.value)} />
 </div>
 </div>
 );
}
","import React, { useState } from "react";
import { NowRecordListConnected } from "@servicenow/react-components/NowRecordListConnected";
import TransactionFilters from "./TransactionFilters";
import "./transactions.css";

const TXN_TABLE = "x_274351_finance_0_txn";
const TXN_COLS = "number,timestamp,type,description,amount,balance_after,status";

function buildQuery(
 accountId: string, fromMonth: string, fromYear: string,
 toMonth: string, toYear: string, search: string
): string {
 const parts = [`account=${accountId}`];
 if (fromMonth && fromYear) {
 parts.push(`timestamp>=${fromYear}-${fromMonth}-01`);
 }
 if (toMonth && toYear) {
 const lastDay = new Date(parseInt(toYear), parseInt(toMonth), 0).getDate();
 parts.push(`timestamp<=${toYear}-${toMonth}-${lastDay}`);
 }
 if (search.trim()) {
 parts.push(`descriptionLIKE${search.trim()}`);
 }
 return parts.join("^");
}

interface Props {
 accountSysId: string;
}

export default function TransactionSection({ accountSysId }: Props) {
 const now = new Date();
 const curMonth = String(now.getMonth() + 1).padStart(2, "0");
 const curYear = String(now.getFullYear());

 const [fromMonth, setFromMonth] = useState(curMonth);
 const [fromYear, setFromYear] = useState(curYear);
 const [toMonth, setToMonth] = useState(curMonth);
 const [toYear, setToYear] = useState(curYear);
 const [searchText, setSearchText] = useState("");

 const query = buildQuery(
 accountSysId, fromMonth, fromYear, toMonth, toYear, searchText
 );

 return (
 <div className="txn-section">
 <div className="txn-section__header">Transactions</div>
 <TransactionFilters
 fromMonth={fromMonth} fromYear={fromYear}
 toMonth={toMonth} toYear={toYear}
 searchText={searchText}
 onFromMonthChange={setFromMonth} onFromYearChange={setFromYear}
 onToMonthChange={setToMonth} onToYearChange={setToYear}
 onSearchChange={setSearchText}
 />
 <NowRecordListConnected
 key={query}
 table={TXN_TABLE}
 columns={TXN_COLS}
 hideHeader={true}
 />
 </div>
 );
}
","import React, { useState, useEffect, useCallback } from "react";
import { NowRecordListConnected } from "@servicenow/react-components/NowRecordListConnected";
import { RecordProvider } from "@servicenow/react-components/RecordContext";
import { FormColumnLayout } from "@servicenow/react-components/FormColumnLayout";
import { FormActionBar } from "@servicenow/react-components/FormActionBar";
import { Button } from "@servicenow/react-components/Button";
import TransactionSection from "./TransactionSection";

interface ViewState {
 view: string;
 recordId: string | null;
}

function getViewFromUrl(): ViewState {
 const params = new URLSearchParams(window.location.search);
 return {
 view: params.get("view") || "list",
 recordId: params.get("id") || null,
 };
}

export default function App() {
 const [currentView, setCurrentView] = useState<ViewState>(getViewFromUrl);

 useEffect(() => {
 const onPopState = () => setCurrentView(getViewFromUrl());
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 const navigateToView = useCallback(
 (viewName: string, recordId?: string | null, { title = "" } = {}) => {
 const params = new URLSearchParams({ view: viewName });
 if (recordId) params.set("id", recordId);
 const relativePath = `${window.location.pathname}?${params}`;
 const pageTitle = title || `My Accounts - ${viewName.charAt(0).toUpperCase() + viewName.slice(1)}`;

 if (window.self !== window.top) {
 (window as any).CustomEvent.fireTop("magellanNavigator.permalink.set", {
 relativePath,
 title: pageTitle,
 });
 }

 window.history.pushState({ viewName, recordId }, "", relativePath);
 document.title = pageTitle;
 setCurrentView({ view: viewName, recordId: recordId || null });
 },
 []
 );

 const { view, recordId } = currentView;

 if (view === "detail" && recordId) {
 return (
 <div>
 <div style={{ padding: "8px 16px" }}>
 <Button
 label="← Back to Accounts"
 variant="secondary"
 onClicked={() => navigateToView("list", null, { title: "My Accounts" })}
 />
 </div>
 <RecordProvider
 table="x_274351_finance_0_accounts"
 sysId={recordId}
 isReadOnly={false}
 >
 <FormActionBar />
 <FormColumnLayout />
 </RecordProvider>
 <TransactionSection accountSysId={recordId} />
 </div>
 );
 }

 return (
 <NowRecordListConnected
 table="x_274351_finance_0_accounts"
 listTitle="My Accounts"
 columns="number,account_type,holder,balance,active"
 onRowClicked={(e: any) => {
 const sysId = e.detail.payload.sys_id;
 const number = e.detail.payload.number;
 navigateToView("detail", sysId, { title: `Account ${number}` });
 }}
 onNewActionClicked={() => navigateToView("create", null, { title: "New Account" })}
 />
 );
}
